'use strict';
const assert=require('node:assert/strict'),crypto=require('node:crypto'),fs=require('node:fs'),path=require('node:path'),os=require('node:os'),{execFileSync,spawnSync}=require('node:child_process');
const {Kmac256,ServerMac}=require('../services/kmac256');
const key=Buffer.from(Array.from({length:32},(_,i)=>0x40+i));
const short=Buffer.from([0,1,2,3]),long=Buffer.from(Array.from({length:200},(_,i)=>i));
// NIST SP 800-185 KMAC samples #4/#5/#6, published output bytes, not values
// generated by the implementation under test. This is not a CMVP certificate.
const vectors=[
 [short,'My Tagged Application','20c570c31346f703c9ac36c61c03cb64c3970d0cfc787e9b79599d273a68d2f7f69d4cc3de9d104a351689f27cf6f5951f0103f33f4f24871024d9c27773a8dd'],
 [long,'','75358cf39e41494e949707927cee0af20a3ff553904c86b08f21cc414bcfd691589d27cf5e15369cbbff8b9a4c2eb17800855d0235ff635da82533ec6b759b69'],
 [long,'My Tagged Application','b58618f71f92e1d56c1b8c55ddd7cd188b97b4ca4d99831eb2699a837da2e4d970fbacfde50033aea585f1a2708510c32d07880801bd182898fe476876fc8965']
];
for(const [input,custom,wanted]of vectors)assert.equal(Kmac256(key,input,custom).toString('hex'),wanted);
let checks=3;const test=(name,fn)=>{fn();checks++;console.log('PASS '+name);};
test('KMAC domain/key/message/output-length separation and caller ownership',()=>{
 const old=Buffer.from(key),message=Buffer.from(long),a=Kmac256(key,message,'one');
 assert.notDeepEqual(a,Kmac256(key,message,'two'));assert.notDeepEqual(a,Kmac256(Buffer.alloc(32),message,'one'));
 message[0]^=1;assert.notDeepEqual(a,Kmac256(key,message,'one'));assert.deepEqual(key,old);
 assert.notDeepEqual(a.subarray(0,32),Kmac256(key,long,'one',32));
 assert.notEqual(ServerMac(key,long,'GAME-STORE-V1'),ServerMac(key,long,'GAME-STORE-V2'));
});
test('Bounded API refuses invalid key, output and customization inputs',()=>{
 for(const bad of [null,'key',Buffer.alloc(31),Buffer.alloc(1025)])assert.throws(()=>Kmac256(bad,short),/KMAC_KEY_INVALID/);
 for(const n of [-1,0,31,1025,Infinity,NaN,32.5])assert.throws(()=>Kmac256(key,short,'',n),/KMAC_OUTPUT_INVALID/);
 assert.throws(()=>Kmac256(key,'text'),/KMAC_INPUT_INVALID/);assert.throws(()=>Kmac256(key,short,'x'.repeat(1025)),/KMAC_CUSTOMIZATION_INVALID/);
 assert.throws(()=>ServerMac(key,short,'arbitrary-domain'),/KMAC_PURPOSE_INVALID/);
});
const temp=fs.mkdtempSync(path.join(os.tmpdir(),'game-kmac256-'));
try{
 test('Vendored SHA-3 files match the package-lock-pinned upstream dependency',()=>{
  const source=path.dirname(require.resolve('@noble/hashes/sha3-addons')),local=path.resolve(__dirname,'../services/vendor/noble-hashes-1.8.0'),manifest=require('../services/vendor/noble-hashes-1.8.0/manifest.json');
  assert.equal(require(path.join(source,'package.json')).version,'1.8.0');
  for(const name of ['sha3.js','sha3-addons.js']){const bytes=fs.readFileSync(path.join(local,name));assert.deepEqual(bytes,fs.readFileSync(path.join(source,name)));assert.equal(crypto.createHash('sha512').update(bytes).digest('hex'),manifest[name]);}
 });
 test('Independent OpenSSL KMAC256 matches block-edge and varied-length inputs',()=>{
  for(const size of [0,1,135,136,137,271,272,273,1024]){
   const input=Buffer.from(Array.from({length:size},(_,i)=>(i*37+11)&255)),file=path.join(temp,'input.bin');fs.writeFileSync(file,input);
   const output=execFileSync('openssl',['mac','-macopt','hexkey:'+key.toString('hex'),'-macopt','custom:GameTest','-macopt','size:64','-in',file,'KMAC256'],{encoding:'utf8',timeout:10000}).trim().toLowerCase();
   assert.equal(Kmac256(key,input,'GameTest').toString('hex'),output,String(size));
  }
 });
 test('Real report store writes KMAC V3, rejects removal/tampering and preserves legacy read migration',()=>{
  const run=(directory,action='load')=>spawnSync(process.execPath,[path.join(__dirname,'kmac-store-fixture.js'),action],{cwd:path.resolve(__dirname,'..'),env:{...process.env,DATA_DIR:directory,STORAGE_ENGINE:'json',HA_ENABLED:'0'},encoding:'utf8',timeout:20000});
  const dataDir=path.join(temp,'store');
  let result=run(dataDir);assert.equal(result.status,0,result.stderr);
  const dir=path.join(dataDir,'desktop-integrity-reports'),file=path.join(dir,'reports.json'),original=fs.readFileSync(file),envelope=JSON.parse(original),secret=fs.readFileSync(path.join(dir,'authority.key'));
  assert.equal(envelope.data.version,3);assert.match(envelope.kmac256Mac,/^[a-f0-9]{128}$/);
  assert.equal(envelope.kmac256Mac,ServerMac(secret,crypto.createHash('sha512').update(JSON.stringify(envelope.data)).digest(),'GAME-INTEGRITY-REPORTS-STORE-V3'));
  for(const alteration of [e=>{delete e.kmac256Mac;},e=>{e.kmac256Mac='0'.repeat(128);},e=>{e.data.records.push({status:'FORGED'});}]){
   const changed=structuredClone(envelope);alteration(changed);fs.writeFileSync(file,JSON.stringify(changed));result=run(dataDir);assert.notEqual(result.status,0);assert.match(result.stderr,/INTEGRITY_REPORT_STORAGE_INVALID/);
  }
  fs.writeFileSync(file,original);assert.equal(run(dataDir).status,0);
  const h=require('../services/extendedHashes');
  for(const version of [1,2]){
   const legacyDir=path.join(temp,'legacy-'+version),reportsDir=path.join(legacyDir,'desktop-integrity-reports');fs.mkdirSync(reportsDir,{recursive:true});fs.writeFileSync(path.join(reportsDir,'authority.key'),secret);
   const data={...envelope.data,version},body={data,mac:crypto.createHmac('sha256',secret).update('GAME-INTEGRITY-REPORTS-V1\n'+JSON.stringify(data)).digest('hex')};
   if(version===2){const k=h.Blake3DeriveKey('GameConnect.Server.IntegrityReports.Store.v2',secret);try{body.blake3Mac=h.Blake3Keyed(k,Buffer.from(JSON.stringify(data))).toString('hex');}finally{k.fill(0);}}
   const legacyFile=path.join(reportsDir,'reports.json');fs.writeFileSync(legacyFile,JSON.stringify(body));result=run(legacyDir);assert.equal(result.status,0,result.stderr);assert.equal(JSON.parse(fs.readFileSync(legacyFile)).data.version,version,'Reading must not silently rewrite an old envelope');
   result=run(legacyDir,'save');assert.equal(result.status,0,result.stderr);assert.equal(JSON.parse(fs.readFileSync(legacyFile)).data.version,3);
   assert.equal(run(legacyDir).status,0);
  }
 });
 console.log('KMAC256 PASS: '+checks+' groups, NIST + OpenSSL + real isolated report-store migration; no Windows/FIPS claim.');
}finally{key.fill(0);fs.rmSync(temp,{recursive:true,force:true});}
